return array(
	array( 'impression', 'インプレッション', 'いんぷれっしょん', 'Impression', '投稿が画面に表示された回数のこと。', array( 'インプレッション（インプ）は、投稿が人の画面に表示された回数です。同じ人に2回表示されれば2回と数えるのが一般的で、「見た人の数」を表すリーチとは違います。', 'インプレッションが多いのに反応が少ないときは、最初の1行や画像で興味を引けていない可能性があります。反対に、インプレッションが少ないときは、投稿する時間帯やハッシュタグ、アルゴリズムに評価されているかを見直しましょう。' ), array( 'reach', 'engagement-rate', 'algorithm' ) ),
	array( 'reach', 'リーチ', 'りーち', 'Reach', '投稿を見た人の数（同じ人は1回と数える）。', array( 'リーチは、投稿やアカウントを見た「人の数」です。同じ人が何度見ても1人と数えます。', 'フォロワー以外へのリーチが増えると、新しいファンを得るきっかけになります。Instagramのインサイトなどで「フォロワー以外」の割合を確かめると、発見されやすい投稿の傾向が分かります。' ), array( 'impression', 'insight', 'discover' ) ),
	array( 'engagement', 'エンゲージメント', 'えんげーじめんと', 'Engagement', 'いいね・コメント・保存・シェアなど、投稿への反応のこと。', array( 'エンゲージメントは、投稿に対する見た人の反応の合計です。いいね・コメント・保存・シェア・リンクのクリックなどが含まれます。', '多くのSNSのアルゴリズムは、エンゲージメントが多い投稿を「良い投稿」と判断して、より多くの人に表示します。特に保存やシェアは、強い関心のしるしとして重く見られやすいと言われています。' ), array( 'engagement-rate', 'algorithm', 'save' ) ),
	array( 'engagement-rate', 'エンゲージメント率', 'えんげーじめんとりつ', 'Engagement rate', '反応の数を、フォロワー数や表示回数で割った割合。', array( 'エンゲージメント率は、投稿への反応（いいね・コメントなど）がどれくらいの割合で起きたかを示す数字です。計算のしかたは主に2通りあり、「反応の数 ÷ フォロワー数」と「反応の数 ÷ インプレッション」があります。', 'フォロワーが多くてもエンゲージメント率が低いと、企業からは「影響力が小さい」と見られることがあります。企業案件では、フォロワー数と同じくらい重視される数字です。' ), array( 'engagement', 'impression', 'influencer-marketing' ) ),
	array( 'algorithm', 'アルゴリズム', 'あるごりずむ', 'Algorithm', 'SNSが「誰に・どの投稿を見せるか」を決める仕組み。', array( 'SNSのアルゴリズムは、たくさんの投稿の中から、一人ひとりに表示する投稿と順番を決める仕組みです。見た人の反応、滞在時間、過去の興味などをもとに自動で判断しています。', 'アルゴリズムの細かい中身は公開されていませんが、多くのSNSで共通するのは「見た人が満足した投稿ほど広がる」ことです。最後まで見られる、保存される、コメントが付く投稿を目指しましょう。' ), array( 'engagement', 'recommend-feed', 'shadowban' ) ),
	array( 'hashtag', 'ハッシュタグ', 'はっしゅたぐ', 'Hashtag', '「#」を付けた言葉。同じ話題の投稿をまとめて探せる。', array( 'ハッシュタグは、「#料理」のように「#」を付けた言葉です。押すと同じハッシュタグの投稿が一覧で見られるので、話題ごとに投稿を探すときに使われます。', '大きすぎるハッシュタグは投稿がすぐに埋もれ、小さすぎると探す人がいません。投稿の内容に合った、ほどよい規模のものを組み合わせるのがおすすめです。SNSによって効果の大きさは違います。' ), array( 'trend', 'discover', 'algorithm' ) ),
	array( 'follower', 'フォロワー', 'ふぉろわー', 'Follower', 'あなたのアカウントをフォローしている人。', array( 'フォロワーは、あなたのアカウントをフォローして、投稿を受け取れるようにしている人です。フォロワー数は、影響力を示す分かりやすい目安として使われます。', 'ただし、数だけでなく「どんな人がフォローしているか」も大切です。発信のテーマに興味を持つフォロワーが多いほど、反応も企業案件の成果も上がりやすくなります。' ), array( 'engagement-rate', 'influencer', 'follow-back' ) ),
	array( 'follow-back', 'フォローバック', 'ふぉろーばっく', 'Follow back', 'フォローしてくれた相手をフォローし返すこと。', array( 'フォローバック（フォロバ）は、フォローしてくれた人をフォローし返すことです。', 'お互いにフォローし合うと交流は深まりますが、テーマと関係のないフォローばかり増えると、タイムラインが見にくくなったり、反応の割合が下がったりすることがあります。自分の発信に合った相手と、自然につながりましょう。' ), array( 'follower', 'engagement-rate' ) ),
	array( 'influencer', 'インフルエンサー', 'いんふるえんさー', 'Influencer', 'SNSなどで多くの人の考えや行動に影響を与える発信者。', array( 'インフルエンサーは、SNSやブログでの発信を通じて、見る人の考えや買い物などの行動に影響を与える人です。フォロワーの規模によって、メガ・マクロ・マイクロ・ナノインフルエンサーと分けて呼ばれることもあります。', '企業はインフルエンサーに商品の紹介を頼む「インフルエンサーマーケティング」を行っています。最近は、フォロワーは少なくても特定の分野で信頼されている発信者も注目されています。' ), array( 'micro-influencer', 'influencer-marketing', 'pr-label' ) ),
	array( 'micro-influencer', 'マイクロインフルエンサー', 'まいくろいんふるえんさー', 'Micro-influencer', 'フォロワーが1万〜10万人ほどの、特定の分野に強い発信者。', array( 'マイクロインフルエンサーは、フォロワーがおおむね1万〜10万人ほどの発信者を指します（数の区切りは会社や記事によって違います）。', 'フォロワーとの距離が近く、反応の割合が高いことが多いため、企業案件で人気があります。特定のジャンルに詳しい人ほど、ファンからの信頼も厚くなります。' ), array( 'influencer', 'engagement-rate', 'niche' ) ),
	array( 'influencer-marketing', 'インフルエンサーマーケティング', 'いんふるえんさーまーけてぃんぐ', 'Influencer marketing', '企業が発信者に商品やサービスの紹介を頼む宣伝の方法。', array( 'インフルエンサーマーケティングは、企業がインフルエンサーに商品やサービスを紹介してもらい、そのファンに知ってもらう宣伝の方法です。', '依頼を受けて紹介するときは、広告であることを分かるように示す必要があります（日本ではステルスマーケティングが規制されています）。発信者にとっては、自分のファンに本当に合う商品かを見極めることが、長く信頼されるコツです。' ), array( 'pr-label', 'stealth-marketing', 'influencer' ) ),
	array( 'pr-label', 'PR表記', 'ぴーあーるひょうき', 'Sponsored disclosure', '企業から依頼された投稿であることを示す「PR」「広告」などの表示。', array( 'PR表記は、企業から依頼やお金・商品を受けて投稿するときに、「#PR」「広告」「プロモーション」のように、それが宣伝であることを見る人に分かるように示すことです。', '日本では2023年10月から、広告であることを隠した宣伝（ステルスマーケティング）が景品表示法の規制の対象になりました。分かりやすい場所に、はっきり表示しましょう。' ), array( 'stealth-marketing', 'influencer-marketing' ) ),
	array( 'stealth-marketing', 'ステルスマーケティング', 'すてるすまーけてぃんぐ', 'Stealth marketing', '広告であることを隠して行う宣伝。日本では規制の対象。', array( 'ステルスマーケティング（ステマ）は、企業からの依頼であることを隠して、ふつうの感想のように見せかけて宣伝することです。', '日本では2023年10月から、景品表示法でステマが規制されています。依頼された投稿には、必ずPR表記を入れましょう。見る人の信頼を守ることは、発信者自身を守ることにもつながります。' ), array( 'pr-label', 'influencer-marketing' ) ),
	array( 'buzz', 'バズる', 'ばずる', 'Going viral', '投稿が短い時間でとても多くの人に広まること。', array( '「バズる」は、投稿が短い時間に一気に広まり、ふだんよりずっと多くの人に見られることです。英語では「go viral」と言います。', 'バズはフォロワーを増やす大きなきっかけになりますが、一度きりで終わることも多いです。バズのあとに、プロフィールや固定した投稿で「どんな発信をしている人か」が伝わるようにしておくと、フォローにつながりやすくなります。' ), array( 'trend', 'algorithm', 'pinned-post' ) ),
	array( 'trend', 'トレンド', 'とれんど', 'Trend', 'いま多くの人が話題にしている言葉や出来事。', array( 'トレンドは、いま多くの人が投稿したり検索したりしている言葉や出来事です。XのトレンドやTikTokの流行りの音源などが代表的です。', 'トレンドに合わせた投稿は見られやすくなりますが、自分の発信テーマと無理なくつながる話題を選ぶのがコツです。このサイトの「トレンド」のページでは、ジャンルごとに伸びている言葉を確かめられます。' ), array( 'buzz', 'hashtag', 'trending-audio' ) ),
	array( 'insight', 'インサイト', 'いんさいと', 'Insights (analytics)', 'SNSの公式の分析画面。見た人の数や反応を確かめられる。', array( 'インサイトは、InstagramやThreadsなどにある公式の分析機能です。投稿ごとのリーチ・インプレッション・保存数や、フォロワーの年齢・地域などを確かめられます。YouTubeでは「アナリティクス」、Xでは「アナリティクス」と呼ばれます。', '数字を定期的に見ると、どんな投稿が伸びやすいか、いつ投稿すると見られやすいかが分かってきます。' ), array( 'reach', 'impression', 'engagement-rate' ) ),
	array( 'save', '保存', 'ほぞん', 'Save', '投稿をあとで見返せるように取っておく機能。', array( '保存は、気に入った投稿をあとで見返せるように、自分だけの一覧に取っておく機能です（Instagramなど）。', '保存される投稿は「何度も見たいほど役に立つ」と判断されやすく、アルゴリズムでも強いしるしになると言われています。まとめ・手順・チェックリストのような投稿は、保存されやすい形です。' ), array( 'engagement', 'algorithm', 'carousel' ) ),
	array( 'carousel', 'カルーセル投稿', 'かるーせるとうこう', 'Carousel post', '複数の画像や動画を、横にめくって見せる投稿。', array( 'カルーセル投稿は、1つの投稿に複数の画像や動画を入れて、横にめくって見てもらう形です。InstagramやThreadsなどで使えます。', 'めくるたびに見る時間が長くなり、最後まで見た人が保存しやすい形です。1枚目で「続きを見たくなる」タイトルを出し、最後の1枚でフォローや保存を呼びかけるのが定番です。' ), array( 'save', 'engagement', 'reels' ) ),
	array( 'reels', 'リール', 'りーる', 'Reels', 'Instagram・Facebookの短い縦型動画。', array( 'リールは、InstagramやFacebookで投稿できる短い縦型の動画です。フォロワー以外にも表示されやすく、新しい人に見つけてもらう入口になります。', '最初の1〜2秒で見続けたくなるかが決まります。字幕を入れると、音を出さずに見ている人にも伝わります。' ), array( 'short-video', 'discover', 'trending-audio' ) ),
	array( 'short-video', 'ショート動画', 'しょーとどうが', 'Short-form video', 'TikTok・YouTubeショート・リールなどの短い縦型動画。', array( 'ショート動画は、数秒〜数分の短い縦型の動画です。TikTok、YouTubeショート、Instagramのリールなどが代表的です。', 'おすすめの一覧から次々と見られるため、フォロワーが少なくても多くの人に届く可能性があります。見る人がどれくらい最後まで見たか（視聴維持率）が、広がり方に大きく影響します。' ), array( 'reels', 'retention-rate', 'recommend-feed' ) ),
	array( 'retention-rate', '視聴維持率', 'しちょういじりつ', 'Audience retention', '動画がどれくらい最後まで見られたかの割合。', array( '視聴維持率は、動画を見始めた人が、どのくらいの割合・長さまで見続けたかを示す数字です。YouTubeのアナリティクスなどで確かめられます。', '多くの動画サービスで、視聴維持率が高い動画ほど、おすすめに表示されやすいと言われています。冒頭で結論や見どころを見せる、間延びする部分を切る、といった工夫が効果的です。' ), array( 'short-video', 'algorithm', 'thumbnail' ) ),
	array( 'thumbnail', 'サムネイル', 'さむねいる', 'Thumbnail', '動画や記事の内容を表す、一覧に出る小さな画像。', array( 'サムネイル（サムネ）は、動画や記事が一覧に並んだときに表示される小さな画像です。', 'クリックされるかどうかを大きく左右するため、YouTubeではタイトルと同じくらい大切だと言われます。スマホの小さな画面でも読める大きな文字と、ひと目で内容が分かる絵づくりを心がけましょう。' ), array( 'ctr', 'retention-rate' ) ),
	array( 'ctr', 'クリック率（CTR）', 'くりっくりつ', 'Click-through rate (CTR)', '表示された回数のうち、クリックされた割合。', array( 'クリック率（CTR）は、サムネイルやリンクが表示された回数のうち、実際にクリックされた割合です。「クリック数 ÷ 表示回数」で計算します。', 'YouTubeでは、表示回数が多いのにクリック率が低いと、サムネイルやタイトルが見る人の興味に合っていない可能性があります。リンクまとめページでも、どのリンクがよく押されるかを見て並べ方を工夫できます。' ), array( 'thumbnail', 'impression', 'link-in-bio' ) ),
	array( 'link-in-bio', 'プロフィールのリンク', 'ぷろふぃーるのりんく', 'Link in bio', 'SNSのプロフィール欄に貼るリンク。まとめページを貼る人が多い。', array( 'SNSのプロフィールには、リンクを貼れる欄があります。投稿の中にリンクを貼れない（または目立たない）SNSでは、「詳しくはプロフィールのリンクから」と案内するのが定番です。', '貼れるリンクの数が限られるため、複数のSNSやお店のページを1ページにまとめた「リンクまとめページ」を貼る人が多くいます。このサイトでは「FolloLink」を無料で作れます。' ), array( 'ctr', 'profile', 'pinned-post' ) ),
	array( 'profile', 'プロフィール', 'ぷろふぃーる', 'Profile / bio', 'アカウントの名前・写真・自己紹介などをまとめた部分。', array( 'プロフィールは、アカウントの名前・写真・自己紹介文・リンクなどをまとめた部分です。初めて来た人がフォローするかを決める、とても大切な場所です。', '「何の発信をしている人か」「フォローすると何が得られるか」が数秒で伝わるようにしましょう。このサイトの「AIプロフィール診断」で、改善のヒントをもらうこともできます。' ), array( 'link-in-bio', 'pinned-post', 'niche' ) ),
	array( 'pinned-post', '固定投稿', 'こていとうこう', 'Pinned post', 'プロフィールのいちばん上に表示し続ける投稿。', array( '固定投稿は、プロフィールを開いたときに、いちばん上に表示され続けるように設定した投稿です（「固定ツイート」「ピン留め」とも言います）。', '自己紹介、いちばん伸びた投稿、販売中の商品の案内など、初めて来た人に最初に見てほしい投稿を固定すると、フォローや購入につながりやすくなります。' ), array( 'profile', 'buzz', 'link-in-bio' ) ),
	array( 'niche', 'ジャンル特化', 'じゃんるとっか', 'Niche', '発信のテーマを1つの分野に絞ること。', array( 'ジャンル特化は、料理・美容・投資など、発信のテーマを1つの分野に絞ることです。英語では「niche（ニッチ）」と言います。', 'テーマが絞られていると、「この人をフォローすれば何が得られるか」が分かりやすくなり、フォロワーが増えやすくなります。企業からも、その分野の専門家として声がかかりやすくなります。' ), array( 'profile', 'micro-influencer', 'persona' ) ),
	array( 'persona', 'ペルソナ', 'ぺるそな', 'Persona', '発信を届けたい相手を、一人の人物として具体的に決めたもの。', array( 'ペルソナは、「30代・共働き・平日の夕食づくりに悩んでいる人」のように、発信を届けたい相手を一人の人物として具体的に決めたものです。', 'ペルソナを決めると、話題選びや言葉づかい、投稿する時間が自然と決まり、発信に一貫性が出ます。' ), array( 'niche', 'profile' ) ),
	array( 'shadowban', 'シャドウバン', 'しゃどうばん', 'Shadowban', '本人は気づかないまま、投稿が他の人に表示されにくくなる状態。', array( 'シャドウバンは、アカウントが凍結されたわけではないのに、投稿が検索やおすすめに表示されにくくなる状態を指す言葉です。SNSの会社は公式にはこの言葉を使わないことが多いですが、ルール違反の疑いがある投稿の表示を制限することはあります。', '同じ内容の繰り返し投稿、関係のないハッシュタグの大量使用、短い時間での大量のフォローなどは避けましょう。' ), array( 'algorithm', 'hashtag', 'community-guidelines' ) ),
	array( 'community-guidelines', 'コミュニティガイドライン', 'こみゅにてぃがいどらいん', 'Community guidelines', 'SNSごとに決められた、投稿や利用のルール。', array( 'コミュニティガイドラインは、各SNSが定めている投稿や利用のルールです。暴力的な内容、なりすまし、スパムなどが禁止されています。', '違反すると、投稿の削除や表示の制限、アカウントの停止になることがあります。収益化を目指す場合は特に、一度は目を通しておきましょう。' ), array( 'shadowban', 'monetization' ) ),
	array( 'monetization', '収益化', 'しゅうえきか', 'Monetization', 'SNSでの発信からお金を得ること。', array( '収益化は、SNSでの発信からお金を得ることです。YouTubeの広告収入、企業案件、商品の紹介料（アフィリエイト）、有料の記事やメンバーシップ、自分の商品の販売など、いくつもの方法があります。', 'SNSごとに収益化の条件（フォロワー数や視聴時間など）が決まっていることがあります。1つの方法に頼らず、いくつかを組み合わせると収入が安定しやすくなります。' ), array( 'affiliate', 'influencer-marketing', 'membership' ) ),
	array( 'affiliate', 'アフィリエイト', 'あふぃりえいと', 'Affiliate marketing', '紹介した商品が売れると、紹介料を受け取れる仕組み。', array( 'アフィリエイトは、ブログやSNSで紹介した商品が、そのリンクから買われたときに、紹介料を受け取れる仕組みです。', 'アフィリエイトのリンクを使った投稿も宣伝にあたるため、PR表記が必要です。自分が本当に良いと思う商品を紹介することが、ファンの信頼と成果の両方につながります。' ), array( 'monetization', 'pr-label' ) ),
	array( 'membership', 'メンバーシップ', 'めんばーしっぷ', 'Membership', '月額の会費を払ったファンだけが見られる特典の仕組み。', array( 'メンバーシップは、ファンが月額の会費を払うと、限定の動画・記事・バッジなどの特典を受け取れる仕組みです。YouTubeのメンバーシップや、noteのメンバーシップなどがあります。', '広告収入と違って、熱心なファンの数がそのまま収入になるため、フォロワーが少なくても始めやすい収益化の方法です。' ), array( 'monetization', 'community' ) ),
	array( 'community', 'コミュニティ', 'こみゅにてぃ', 'Community', '共通の興味でつながったファンや仲間の集まり。', array( 'コミュニティは、発信者を中心に、同じ興味を持つ人どうしがつながる集まりです。オンラインサロン、Discordのサーバー、メンバーシップなどの形があります。', 'ファンどうしの交流が生まれると、発信者が投稿しなくても場が盛り上がり、長く応援してもらえる関係につながります。' ), array( 'membership', 'ugc' ) ),
